class Account {
  readonly id = crypto.randomUUID();
  protected owner: string;
  private balance = 0;
  constructor(owner: string) {
    this.owner = owner;
  }
  deposit(amount: number): void {
    this.balance += amount;
  }
}
const account = new Account("Lisa");
account.deposit(50);
console.log(account.balance);

class Customer {
  private _discount = 0;
  constructor(public firstname: string, public lastname: string) {}
  get fullName(): string {
    return `${this.firstname} ${this.lastname}`;
  }
  get discount(): number {
    return this._discount;
  }
  set discount(value: number) {
    if (value < 0 || value > 100) throw new Error("0 bis 100");
    this._discount = value;
  }
}

interface Labelled {
  getLabel(): string;
}
class Customer implements Labelled {
  constructor(public firstname: string, public lastname: string) {}
  getLabel(): string {
    return `Kunde: ${this.firstname} ${this.lastname}`;
  }
}
function printLabel(item: Labelled): void {
  console.log(item.getLabel());
}
printLabel(new Customer("Lisa", "Simpson"));

class VipCustomer extends Customer {
  constructor(
    firstname: string,
    lastname: string,
    public discount: number,
  ) {
    super(firstname, lastname);
  }
  override getLabel(): string {
    return super.getLabel() + ` - VIP -${this.discount}%`;
  }
}
const ned = new VipCustomer("Ned", "Flanders", 10);
console.log(ned.getLabel());

